        INSERT INTO TB_KPI_TARGET_HIST_MASTER (
		        HIST_ID
		      , KPI_YEAR
		      , CHG_REASON
		      , MOD_USER 
		      , HIST_REG_DT 
        )
        VALUES (
             #{histId}
           , #{year}
           , #{reason}           
           , #{userId}
           , GETDATE() 
        )

INSERT INTO TB_KPI_TARGET_HIST_DETAIL ( HIST_ID , WAVE_CD
, FAB_IN , B1ST , B2ST , B3ST , B4ST , B5ST
, PG_IN , A1ST , A2ST , A3ST , A4ST , A5ST
, FAB_OUT , REG_DT , REG_USER
) VALUES (
#{histId} ,#{row.waveCd}
,TRY_CAST(ISNULL(#{row.fabIn}, '0') AS NUMERIC(18,2)) ,TRY_CAST(ISNULL(#{row.b1st}, '0') AS NUMERIC(18,2)) ,TRY_CAST(ISNULL(#{row.b2st}, '0') AS NUMERIC(18,2)) ,TRY_CAST(ISNULL(#{row.b3st}, '0') AS NUMERIC(18,2)) ,TRY_CAST(ISNULL(#{row.b4st}, '0') AS NUMERIC(18,2)) ,TRY_CAST(ISNULL(#{row.b5st}, '0') AS NUMERIC(18,2))
,TRY_CAST(ISNULL(#{row.pgin}, '0') AS NUMERIC(18,2)) ,TRY_CAST(ISNULL(#{row.a1st}, '0') AS NUMERIC(18,2)) ,TRY_CAST(ISNULL(#{row.a2st}, '0') AS NUMERIC(18,2)) ,TRY_CAST(ISNULL(#{row.a3st}, '0') AS NUMERIC(18,2)) ,TRY_CAST(ISNULL(#{row.a4st}, '0') AS NUMERIC(18,2)) ,TRY_CAST(ISNULL(#{row.a5st}, '0') AS NUMERIC(18,2))
,TRY_CAST(ISNULL(#{row.fabOut}, '0') AS NUMERIC(18,2)) ,GETDATE() ,#{userId} );

mapper.update:
        MERGE INTO TB_KPI_M AS Target
        USING (SELECT #{year} AS YEAR, #{row.kpiCd} AS KPI_CD) AS Source
        ON (Target.YEAR = Source.YEAR AND Target.KPI_CD = Source.KPI_CD)        

        WHEN MATCHED THEN
            UPDATE SET 
		        KPI_NM = #{row.kpiNm}
		      , GUBUN_VAL = #{row.gubunVal}
		      , GUBUN_SIGN = #{row.gubunSign}
		      , KPI_VAL = #{row.kpiVal}

		      , [1st_Sign] = #{row.v1stSign}
		      , [1st_Val] = #{row.v1stVal}
		      , [1st_Mon] = #{row.v1stMon}
		      , [1st_UseYn] = #{row.v1stUseYn}
		      , [2st_Sign] = #{row.v2stSign}

		      , [2st_Val] = #{row.v2stVal}
		      , [2st_Mon] = #{row.v2stMon}
		      , [2st_UseYn] = #{row.v2stUseYn}
		      , [3st_Sign] = #{row.v3stSign}
		      , [3st_Val] = #{row.v3stVal}

		      , [3st_Mon] = #{row.v3stMon}
		      , [3st_UseYn] = #{row.v3stUseYn}
		      , [4st_Sign] = #{row.v4stSign}
		      , [4st_Val] = #{row.v4stVal}
		      , [4st_Mon] = #{row.v4stMon}

		      , [4st_UseYn] = #{row.v4stUseYn}                

              , MOD_DT   = GETDATE()
              , MOD_ID = #{userId}

        WHEN NOT MATCHED THEN
            INSERT ( [YEAR]
			      , KPI_CD
			      , KPI_NM
			      , GUBUN_VAL
			      , GUBUN_SIGN
			      , KPI_VAL

			      , [1st_Sign]
			      , [1st_Val]
			      , [1st_Mon]
			      , [1st_UseYn]
			      , [2st_Sign]

			      , [2st_Val]
			      , [2st_Mon]
			      , [2st_UseYn]
			      , [3st_Sign]
			      , [3st_Val]

			      , [3st_Mon]
			      , [3st_UseYn]
			      , [4st_Sign]
			      , [4st_Val]
			      , [4st_Mon]

			      , [4st_UseYn]

                   , REG_DT
                   , REG_ID
            )
            VALUES ( Source.YEAR
                   , Source.KPI_CD
			       , #{row.kpiNm}
			       , #{row.gubunVal}
			       , #{row.gubunSign}
			       , #{row.kpiVal}

			       , #{row.v1stSign}
			       , #{row.v1stVal}
			       , #{row.v1stMon}
			       , #{row.v1stUseYn}
			       , #{row.v2stSign}

			       , #{row.v2stVal}
			       , #{row.v2stMon}
			       , #{row.v2stUseYn}
			       , #{row.v3stSign}
			       , #{row.v3stVal}

			       , #{row.v3stMon}
			       , #{row.v3stUseYn}
			       , #{row.v4stSign}
			       , #{row.v4stVal}
			       , #{row.v4stMon}

			       , #{row.v4stUseYn}

                   , GETDATE() 
                   , #{userId}
            );
